//! Rust SDK types: Protobuf (prost) and JSON (serde) from one definition,
//! plus the method table, typed requests and responses, and a dispatcher.

use std::fmt::Write as _;

use crate::schema::{Field, Kind, Schema, camel, snake};

pub fn generate(s: &Schema) -> String {
    let mut o = String::new();
    o.push_str(
        "// @generated by tools/api-gen from crates/api/schema/api.yaml. Do not edit;\n\
         // run `cargo xtask api` instead.\n\n\
         #![allow(clippy::all, clippy::pedantic, missing_docs)]\n\n\
         use serde::{Deserialize, Serialize};\n\n",
    );
    let _ = writeln!(o, "pub const PACKAGE: &str = \"{}\";", s.package);
    let _ = writeln!(o, "pub const PROTOCOL_MAJOR: u32 = {};", s.version.major);
    let _ = writeln!(o, "pub const PROTOCOL_MINOR: u32 = {};\n", s.version.minor);

    for (name, t) in s.enums() {
        doc(&mut o, "", t.doc.as_deref());
        o.push_str(
            "#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, ::prost::Enumeration)]\n\
             #[repr(i32)]\n",
        );
        let _ = writeln!(o, "pub enum {name} {{");
        for v in &t.values {
            doc(&mut o, "    ", v.doc.as_deref());
            let _ = writeln!(o, "    {} = {},", camel(&v.name), v.n);
        }
        o.push_str("}\n\n");
        let _ = writeln!(o, "impl {name} {{");
        o.push_str("    /// The JSON and Luau spelling.\n    pub fn name(self) -> &'static str {\n        match self {\n");
        for v in &t.values {
            let _ = writeln!(o, "            Self::{} => \"{}\",", camel(&v.name), v.name);
        }
        o.push_str("        }\n    }\n\n    pub fn from_name(name: &str) -> Option<Self> {\n        match name {\n");
        for v in &t.values {
            let _ = writeln!(
                o,
                "            \"{}\" => Some(Self::{}),",
                v.name,
                camel(&v.name)
            );
        }
        o.push_str("            _ => None,\n        }\n    }\n}\n\n");
        // JSON carries enum names; unknown numbers from a newer peer stay numbers.
        let module = format!("{}_json", snake(name));
        let _ = writeln!(
            o,
            "mod {module} {{\n    use super::{name};\n\n\
             pub fn serialize<S: serde::Serializer>(v: &i32, s: S) -> Result<S::Ok, S::Error> {{\n        \
             match {name}::try_from(*v) {{\n            Ok(e) => s.serialize_str(e.name()),\n            \
             Err(_) => s.serialize_i32(*v),\n        }}\n    }}\n\n\
             pub fn deserialize<'de, D: serde::Deserializer<'de>>(d: D) -> Result<i32, D::Error> {{\n        \
             crate::json::enum_value(d, |n| {name}::from_name(n).map(|e| e as i32))\n    }}\n}}\n"
        );
    }

    for (name, t) in s.messages() {
        doc(&mut o, "", t.doc.as_deref());
        o.push_str(
            "#[derive(Clone, PartialEq, ::prost::Message, Serialize, Deserialize)]\n#[serde(default)]\n",
        );
        let _ = writeln!(o, "pub struct {name} {{");
        for f in &t.fields {
            field(&mut o, s, f);
        }
        if let Some(of) = &t.oneof {
            let tags: Vec<String> = of.variants.iter().map(|v| v.n.to_string()).collect();
            let _ = writeln!(
                o,
                "    #[prost(oneof = \"{}::{}\", tags = \"{}\")]\n    \
                 #[serde(skip_serializing_if = \"Option::is_none\")]\n    \
                 pub {}: Option<{}::{}>,",
                snake(name),
                camel(&of.name),
                tags.join(", "),
                of.name,
                snake(name),
                camel(&of.name)
            );
        }
        o.push_str("}\n\n");
        if let Some(of) = &t.oneof {
            let _ = writeln!(
                o,
                "pub mod {} {{\n    use serde::{{Deserialize, Serialize}};\n\n    \
                 #[derive(Clone, PartialEq, ::prost::Oneof, Serialize, Deserialize)]\n    \
                 #[serde(rename_all = \"snake_case\")]\n    pub enum {} {{",
                snake(name),
                camel(&of.name)
            );
            for v in &of.variants {
                doc(&mut o, "        ", v.doc.as_deref());
                let _ = writeln!(
                    o,
                    "        #[prost(message, tag = \"{}\")]\n        {}(super::{}),",
                    v.n,
                    camel(&v.name),
                    v.ty
                );
            }
            o.push_str("    }\n}\n\n");
        }
    }

    methods(&mut o, s);
    notifications(&mut o, s);
    o
}

fn notifications(o: &mut String, s: &Schema) {
    o.push_str("\n/// Topics of what the daemon pushes.\npub mod topic {\n");
    for n in &s.notifications {
        doc(o, "    ", n.doc.as_deref());
        let _ = writeln!(
            o,
            "    pub const {}: &str = \"{}\";",
            n.topic.replace('.', "_").to_ascii_uppercase(),
            n.topic
        );
    }
    o.push_str("}\n\n");
    o.push_str(
        "/// Something the daemon pushed, typed by its topic.\n#[derive(Debug, Clone, PartialEq)]\npub enum Notification {\n",
    );
    for n in &s.notifications {
        let _ = writeln!(o, "    {}({}),", camel(&n.topic), n.payload);
    }
    o.push_str("}\n\nimpl Notification {\n    pub fn topic(&self) -> &'static str {\n        match self {\n");
    for n in &s.notifications {
        let _ = writeln!(
            o,
            "            Self::{}(_) => \"{}\",",
            camel(&n.topic),
            n.topic
        );
    }
    o.push_str("        }\n    }\n\n    pub fn encode(&self) -> Vec<u8> {\n        match self {\n");
    for n in &s.notifications {
        let _ = writeln!(
            o,
            "            Self::{}(v) => ::prost::Message::encode_to_vec(v),",
            camel(&n.topic)
        );
    }
    o.push_str("        }\n    }\n\n    pub fn decode(topic: &str, bytes: &[u8]) -> Result<Self, crate::CallError> {\n        match topic {\n");
    for n in &s.notifications {
        let _ = writeln!(
            o,
            "            \"{}\" => Ok(Self::{}(::prost::Message::decode(bytes)?)),",
            n.topic,
            camel(&n.topic)
        );
    }
    o.push_str("            other => Err(crate::CallError::UnknownMethod(other.to_owned())),\n        }\n    }\n\n    pub fn to_json(&self) -> serde_json::Value {\n        match self {\n");
    for n in &s.notifications {
        let _ = writeln!(
            o,
            "            Self::{}(v) => serde_json::to_value(v).unwrap_or_default(),",
            camel(&n.topic)
        );
    }
    o.push_str("        }\n    }\n\n    pub fn from_json(topic: &str, value: serde_json::Value) -> Result<Self, crate::CallError> {\n        match topic {\n");
    for n in &s.notifications {
        let _ = writeln!(
            o,
            "            \"{}\" => Ok(Self::{}(serde_json::from_value(value)?)),",
            n.topic,
            camel(&n.topic)
        );
    }
    o.push_str("            other => Err(crate::CallError::UnknownMethod(other.to_owned())),\n        }\n    }\n}\n");
}

fn field(o: &mut String, s: &Schema, f: &Field) {
    doc(o, "    ", f.doc.as_deref());
    let kind = s.kind(&f.ty).unwrap_or(Kind::Scalar);
    let (prost, rust) = match kind {
        Kind::Message => ("message".to_owned(), f.ty.clone()),
        Kind::Enum => (format!("enumeration = \"{}\"", f.ty), "i32".to_owned()),
        Kind::Scalar => match f.ty.as_str() {
            "string" => ("string".into(), "String".into()),
            "bool" => ("bool".into(), "bool".into()),
            "u32" => ("uint32".into(), "u32".into()),
            "u64" => ("uint64".into(), "u64".into()),
            "i32" => ("int32".into(), "i32".into()),
            "i64" => ("int64".into(), "i64".into()),
            _ => ("bytes = \"vec\"".into(), "Vec<u8>".into()),
        },
    };
    let (card, ty) = if f.repeated {
        (", repeated", format!("Vec<{rust}>"))
    } else if f.optional || kind == Kind::Message {
        (", optional", format!("Option<{rust}>"))
    } else {
        ("", rust)
    };
    let _ = writeln!(o, "    #[prost({prost}{card}, tag = \"{}\")]", f.n);
    if kind == Kind::Enum {
        let _ = writeln!(o, "    #[serde(with = \"{}_json\")]", snake(&f.ty));
    } else if f.ty == "bytes" {
        let with = if f.repeated {
            "crate::json::base64_list"
        } else if f.optional {
            "crate::json::base64_option"
        } else {
            "crate::json::base64"
        };
        let _ = writeln!(o, "    #[serde(with = \"{with}\")]");
    }
    if ty.starts_with("Option<") {
        o.push_str("    #[serde(skip_serializing_if = \"Option::is_none\")]\n");
    }
    let _ = writeln!(o, "    pub {}: {ty},", f.name);
}

fn methods(o: &mut String, s: &Schema) {
    o.push_str("/// Method names.\npub mod method {\n");
    for m in &s.methods {
        let _ = writeln!(
            o,
            "    pub const {}: &str = \"{}\";",
            m.method.replace('.', "_").to_ascii_uppercase(),
            m.method
        );
    }
    o.push_str("}\n\n");

    o.push_str(
        "#[derive(Debug, Clone, Copy, PartialEq, Eq)]\npub struct MethodInfo {\n    \
         pub name: &'static str,\n    pub params: &'static str,\n    pub result: &'static str,\n    \
         pub mutation: bool,\n    pub doc: &'static str,\n}\n\n\
         pub const METHODS: &[MethodInfo] = &[\n",
    );
    for m in &s.methods {
        let _ = writeln!(
            o,
            "    MethodInfo {{ name: \"{}\", params: \"{}\", result: \"{}\", mutation: {}, doc: {:?} }},",
            m.method,
            m.params,
            m.result,
            m.mutation,
            m.doc.as_deref().unwrap_or("")
        );
    }
    o.push_str("];\n\n");

    for (which, ty_of) in [("Request", 0), ("Response", 1)] {
        let _ = writeln!(
            o,
            "/// A typed {} for one method.\n#[derive(Debug, Clone, PartialEq)]\npub enum {which} {{",
            which.to_ascii_lowercase()
        );
        for m in &s.methods {
            let ty = if ty_of == 0 { &m.params } else { &m.result };
            let _ = writeln!(o, "    {}({ty}),", camel(&m.method));
        }
        o.push_str("}\n\n");
        let _ = writeln!(
            o,
            "impl {which} {{\n    pub fn method(&self) -> &'static str {{\n        match self {{"
        );
        for m in &s.methods {
            let _ = writeln!(
                o,
                "            Self::{}(_) => \"{}\",",
                camel(&m.method),
                m.method
            );
        }
        o.push_str("        }\n    }\n\n    /// Protobuf encoding of the payload.\n    pub fn encode(&self) -> Vec<u8> {\n        match self {\n");
        for m in &s.methods {
            let _ = writeln!(
                o,
                "            Self::{}(v) => ::prost::Message::encode_to_vec(v),",
                camel(&m.method)
            );
        }
        o.push_str(
            "        }\n    }\n\n    pub fn decode(method: &str, bytes: &[u8]) -> Result<Self, crate::CallError> {\n        match method {\n",
        );
        for m in &s.methods {
            let _ = writeln!(
                o,
                "            \"{}\" => Ok(Self::{}(::prost::Message::decode(bytes)?)),",
                m.method,
                camel(&m.method)
            );
        }
        o.push_str(
            "            other => Err(crate::CallError::UnknownMethod(other.to_owned())),\n        }\n    }\n\n    \
             pub fn to_json(&self) -> serde_json::Value {\n        match self {\n",
        );
        for m in &s.methods {
            let _ = writeln!(
                o,
                "            Self::{}(v) => serde_json::to_value(v).unwrap_or_default(),",
                camel(&m.method)
            );
        }
        o.push_str(
            "        }\n    }\n\n    pub fn from_json(method: &str, value: serde_json::Value) -> Result<Self, crate::CallError> {\n        match method {\n",
        );
        for m in &s.methods {
            let _ = writeln!(
                o,
                "            \"{}\" => Ok(Self::{}(serde_json::from_value(value)?)),",
                m.method,
                camel(&m.method)
            );
        }
        o.push_str(
            "            other => Err(crate::CallError::UnknownMethod(other.to_owned())),\n        }\n    }\n}\n\n",
        );
    }

    o.push_str(
        "/// One implementation of every method, shared by the binary and the\n\
         /// JSON-RPC endpoints.\npub trait Service: Sync {\n",
    );
    for m in &s.methods {
        doc(o, "    ", m.doc.as_deref());
        let _ = writeln!(
            o,
            "    fn {}(&self, params: {}) -> impl ::core::future::Future<Output = Result<{}, RpcError>> + Send;",
            m.method.replace('.', "_"),
            m.params,
            m.result
        );
    }
    o.push_str(
        "}\n\n/// Route a typed request to its method.\n\
         pub async fn dispatch<S: Service>(service: &S, request: Request) -> Result<Response, RpcError> {\n    match request {\n",
    );
    for m in &s.methods {
        let _ = writeln!(
            o,
            "        Request::{v}(p) => service.{f}(p).await.map(Response::{v}),",
            v = camel(&m.method),
            f = m.method.replace('.', "_")
        );
    }
    o.push_str("    }\n}\n");
}

fn doc(o: &mut String, indent: &str, doc: Option<&str>) {
    if let Some(d) = doc {
        for line in d.lines() {
            let _ = writeln!(o, "{indent}/// {line}");
        }
    }
}
